#!/usr/bin/env node
// GENERATED by scripts/gen/build.mjs from gen/tools/module-context.mjs - edit the sources, not this file.
// Prints the context an agent needs before touching a module: its AGENTS.md, projects, public contract types,
// the contracts it consumes, who consumes its contract, and how to test it.
// Usage: node module-context.mjs <module name | path to a file or folder> [--json] [--root <repo>]
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { basename, dirname, join, relative, resolve } from "node:path";
const SKIP_DIRS = new Set([
  "bin",
  "obj",
  "node_modules",
  ".git",
  ".vs",
  "TestResults",
  "artifacts",
]);
const ROLE_SUFFIX =
  /\.(Contracts|Tests|UnitTests|IntegrationTests|Infrastructure|Domain|Application|Api|Endpoints|Migrations)$/i;
const SHARED_NAME = /(^|\.)(Shared|SharedKernel|BuildingBlocks|Common|Kernel)(\.|$)/i;
const posix = (p) => p.split("\\").join("/");

function* walkFiles(dir, depth = 0) {
  for (const e of readdirSync(dir, { withFileTypes: true })) {
    if (e.isDirectory()) {
      if (!SKIP_DIRS.has(e.name) && depth < 8) yield* walkFiles(join(dir, e.name), depth + 1);
    } else yield join(dir, e.name);
  }
}

function readProjects(root) {
  const projects = [];
  for (const file of walkFiles(root)) {
    if (!file.endsWith(".csproj")) continue;
    const text = readFileSync(file, "utf8");
    const all = (re) => [...text.matchAll(re)].map((m) => m[1]);
    const name = basename(file, ".csproj");
    projects.push({
      name,
      file,
      dir: dirname(file),
      rel: posix(relative(root, file)),
      refs: all(/<ProjectReference\s[^>]*?Include\s*=\s*"([^"]+)"/gi).map((r) =>
        resolve(dirname(file), r.split("\\").join("/")),
      ),
      packages: all(/<PackageReference\s[^>]*?Include\s*=\s*"([^"]+)"/gi),
      frameworks: all(/<FrameworkReference\s[^>]*?Include\s*=\s*"([^"]+)"/gi),
      ivt: all(/<InternalsVisibleTo\s[^>]*?Include\s*=\s*"([^"]+)"/gi),
      tfms: (/<TargetFrameworks?>([^<]+)</i.exec(text)?.[1] ?? "").split(";").filter(Boolean),
      isTest:
        /<IsTestProject>\s*true/i.test(text) ||
        /Microsoft\.NET\.Test\.Sdk/.test(text) ||
        /\.(Unit|Integration)?Tests?$/i.test(name),
    });
  }
  return detectModules(projects, root);
}

function detectModules(projects, root) {
  let config = {};
  try {
    config = JSON.parse(readFileSync(join(root, "modules.json"), "utf8"));
  } catch {
    // no config: use conventions
  }
  const bases = projects.map((p) => p.name.replace(ROLE_SUFFIX, ""));
  const multi = bases.filter((b) => b.includes("."));
  const first = multi.map((b) => b.split(".")[0]);
  const top = [...new Set(first)]
    .map((s) => [s, first.filter((x) => x === s).length])
    .sort((a, b) => b[1] - a[1])[0];
  const prefix = top && multi.length >= 3 && top[1] / bases.length >= 0.8 ? `${top[0]}.` : "";

  for (const [i, p] of projects.entries()) {
    const contracts = /\.Contracts$/i.test(p.name);
    p.role = p.isTest ? "test" : contracts ? "contracts" : "impl";
    let module;
    const confHit = Object.entries(config.modules ?? {}).find(([, paths]) =>
      paths.some((x) => p.rel.startsWith(x)),
    );
    const m = /(?:^|\/)[Mm]odules\/([^/]+)\//.exec(`/${p.rel}`);
    if (confHit) module = confHit[0];
    else if ((config.shared ?? []).some((x) => p.rel.startsWith(x))) module = null;
    else if (m) module = m[1];
    else if (SHARED_NAME.test(bases[i])) module = null;
    else module = prefix && bases[i].startsWith(prefix) ? bases[i].slice(prefix.length) : bases[i];
    p.module = module;
    if (module === null) p.role = "shared";
  }
  return projects;
}

const projectOf = (projects, file) =>
  projects
    .filter((p) => resolve(file).startsWith(`${p.dir}${process.platform === "win32" ? "\\" : "/"}`))
    .sort((a, b) => b.dir.length - a.dir.length)[0];
const byFile = (projects) => new Map(projects.map((p) => [resolve(p.file), p]));
const moduleNames = (projects) =>
  [...new Set(projects.map((p) => p.module).filter(Boolean))].sort();
function tryRead(path) {
  try {
    return readFileSync(path, "utf8");
  } catch {
    return undefined;
  }
}

const args = process.argv.slice(2);
const flag = (n) => args.includes(n);
const ri = args.indexOf("--root");
const root = resolve(ri >= 0 ? args[ri + 1] : process.cwd());
const target = args.find((a, i) => !a.startsWith("--") && args[i - 1] !== "--root");
const projects = readProjects(root);
const byPath = byFile(projects);
const modules = moduleNames(projects);
if (!target) {
  console.error(
    "Usage: module-context.mjs <module name | file or folder path>\nModules found: " +
      (modules.join(", ") || "none"),
  );
  process.exit(2);
}

let moduleName = modules.find((m) => m.toLowerCase() === target.toLowerCase());
if (!moduleName) {
  const abs = resolve(root, target);
  const p = existsSync(abs)
    ? (projectOf(projects, abs) ?? projects.find((x) => abs === x.dir))
    : undefined;
  moduleName = p?.module ?? undefined;
}
const mine = moduleName ? projects.filter((p) => p.module === moduleName) : projects;
const rel = (p) => posix(relative(root, p));

const typesIn = (project) => {
  const out = [];
  for (const file of walkFiles(project.dir)) {
    if (!file.endsWith(".cs")) continue;
    for (const line of (tryRead(file) ?? "").split("\n")) {
      const m =
        /^\s*public\s+(?:(?:sealed|static|abstract|partial|readonly)\s+)*(interface|class|record(?:\s+struct|\s+class)?|struct|enum)\s+(\w+)/.exec(
          line,
        );
      if (m) out.push(`${m[1].replace(/\s+/g, " ")} ${m[2]}`);
    }
  }
  return out.sort();
};

const contracts = mine.filter((p) => p.role === "contracts");
const consumed = [
  ...new Set(
    mine
      .filter((p) => p.role !== "contracts")
      .flatMap((p) =>
        p.refs
          .map((r) => byPath.get(r))
          .filter((t) => t && t.module && t.module !== moduleName && t.role === "contracts")
          .map((t) => t.name),
      ),
  ),
].sort();
const consumers = moduleName
  ? [
      ...new Set(
        projects
          .filter(
            (p) =>
              p.module &&
              p.module !== moduleName &&
              p.refs.some(
                (r) => byPath.get(r)?.module === moduleName && byPath.get(r)?.role === "contracts",
              ),
          )
          .map((p) => p.module),
      ),
    ].sort()
  : [];
const agentsFile = [
  ...new Set(mine.filter((p) => p.role === "impl").flatMap((p) => [p.dir, dirname(p.dir)])),
]
  .map((d) => join(d, "AGENTS.md"))
  .find((f) => existsSync(f));
const agents = agentsFile
  ? (tryRead(agentsFile) ?? "").split("\n").slice(0, 60).join("\n")
  : undefined;
const tests = mine.filter((p) => p.role === "test");

const result = {
  module: moduleName ?? "(none: whole repository treated as one module)",
  agentsFile: agentsFile ? rel(agentsFile) : null,
  projects: mine.map((p) => ({ name: p.name, role: p.role, path: p.rel, tfms: p.tfms })),
  contractTypes: Object.fromEntries(contracts.map((c) => [c.name, typesIn(c)])),
  consumesContracts: consumed,
  consumedBy: consumers,
  testCommands: tests.map((t) => `dotnet test ${t.rel}`),
};
if (flag("--json")) console.log(JSON.stringify({ ...result, agents }, null, 2));
else {
  console.log(`# Module: ${result.module}`);
  console.log(`AGENTS.md: ${result.agentsFile ?? "none (run dotnet-conventions-bootstrap)"}`);
  if (agents) console.log(`\n--- AGENTS.md (first 60 lines) ---\n${agents}\n---`);
  console.log("\n## Projects");
  for (const p of result.projects)
    console.log(
      `- ${p.role.padEnd(9)} ${p.name}  (${p.path}${p.tfms.length ? `, ${p.tfms.join(";")}` : ""})`,
    );
  console.log("\n## Public contract");
  if (!contracts.length) console.log("- no .Contracts project found");
  for (const [name, types] of Object.entries(result.contractTypes))
    console.log(`- ${name}: ${types.length ? types.join(", ") : "(no public types)"}`);
  console.log(`\n## Consumes contracts of: ${consumed.length ? consumed.join(", ") : "none"}`);
  console.log(
    `## Contract consumed by modules: ${consumers.length ? consumers.join(", ") : "none"}`,
  );
  console.log("\n## How to test");
  console.log(
    result.testCommands.length
      ? result.testCommands.map((c) => `- ${c}`).join("\n")
      : "- no test project found for this module",
  );
}
